// ❌ OLD: Reflection for repeated invocation. Every call goes through
// Method.invoke, which performs access checks, argument boxing/
// unboxing, and varargs handling — significant overhead per call, and
// the JIT cannot easily inline the reflective dispatch.
import java.lang.reflect.Method;

public class InvokeLegacy {
  public static void main(String[] args) throws Exception {
    Method m = Foo.class.getMethod("bar", int.class); // ❌ OLD: lookup

    Foo foo = new Foo();
    long t0 = System.nanoTime();
    for (int i = 0; i < 1_000_000; i++) {
      m.invoke(foo, i); // ❌ OLD: reflective call per iteration
    }
    System.out.println("reflection took " + (System.nanoTime() - t0) / 1_000_000 + "ms");
  }
}

import java.lang.invoke.*;

// ✅ NEW: A MethodHandle is typed, pre-bound, and directly invocable.
// invokeExact skips argument conversion; the JIT can inline the call
// target, making hot loops much faster than reflection.
public class InvokeModern {
  public static void main(String[] args) throws Throwable {
    MethodHandles.Lookup lookup = MethodHandles.lookup();
    // ✅ NEW: typed handle with exact MethodType
    MethodHandle bar = lookup.findVirtual(
        Foo.class, "bar", MethodType.methodType(void.class, int.class));

    Foo foo = new Foo();
    long t0 = System.nanoTime();
    for (int i = 0; i < 1_000_000; i++) {
      bar.invokeExact(foo, i); // ✅ NEW: direct, no reflection checks
    }
    System.out.println("methodhandle took " + (System.nanoTime() - t0) / 1_000_000 + "ms");
  }
}

